fun main() {
    println(Int.MAX_VALUE + 1)
    println(Int.MIN_VALUE - 1)
    println(Long.MAX_VALUE + 1)
    println(Long.MIN_VALUE - 1)
    println(Int.MAX_VALUE * 2)
    println(Int.MAX_VALUE.toLong() * 2)
    println(Long.MAX_VALUE * 3)
    println(-Int.MIN_VALUE)
    println(Math.abs(Int.MIN_VALUE))
    println(Int.MIN_VALUE / -1)
    println(Long.MIN_VALUE / -1)
    println(7 / 2 to -7 / 2)
    println(7 % 3 to -7 % 3 to 7 % -3)
    println((-7).mod(3) to (-7).rem(3))
    println(Math.floorMod(-7, 3) to Math.floorDiv(-7, 2))
    println(1L shl 40)
    println(1 shl 33)
    println(-1 ushr 28)
    println(-1L ushr 60)
    println(-16 shr 2)
    println(300.toByte())
    println(200.toByte().toInt())
    println(40000.toShort())
    println(3_000_000_000L.toInt())
    println(3.99.toInt() to -3.99.toInt())
    println(1e20.toLong() to Double.NaN.toInt())
    println(Long.MAX_VALUE.toDouble())
    println((0.1 + 0.2).toString())
    println(10 / 3.0)
    println(1.0 / 0 to -1.0 / 0)
    println(0.0 / 0 == 0.0 / 0)
    println(Int.MAX_VALUE.inc() == Int.MIN_VALUE)
    println(5.coerceIn(1, 3) to (-5).coerceAtLeast(0) to 5.coerceAtMost(2))
    println(Long.MAX_VALUE.toString().length)
    println(123456789L * 987654321L)
}
